#!/usr/bin/env bash
# The commit-time detectors, generated by relearn from the rule files.
# Edit the rules, never this script: `relearn verify` reports a hand edit.
# A repository's own pre-commit calls it; relearn never installs it:
#   bash relearn-pre-commit.sh [name ...]   0 clean, 1 blocked, 2 could not check
# With no name, every detector below runs. It reads the index, never the
# working tree, so a file fixed on disk and not re-staged still blocks.
# A `listed-path` detector reads its list from the file this clone names with
#   git config --local relearn.<name>.list <file>
# and with no list, or one it cannot read, it cannot check: exit 2, never 0.
set -uo pipefail
export LC_ALL=C

disarmed() {
  printf '[relearn-pre-commit] DISARMED (exit 2, not a pass): %s\n' "$1" >&2
  exit 2
}
command -v git >/dev/null 2>&1 || disarmed "git is not on PATH"
top="$(git rev-parse --show-toplevel 2>/dev/null)" || disarmed "this is not a git checkout"
cd "$top" || disarmed "the checkout's top level cannot be entered"
work="$(mktemp -d)" || disarmed "no scratch directory"
trap 'rm -rf "$work"' EXIT
git diff --cached --name-only -z --diff-filter=ACMR > "$work/staged" \
  || disarmed "git could not list the staged paths"
blocked=0

# in_scope <path> <files ERE> <exclude ERE, or empty>: 0 in scope, 1 not.
in_scope() {
  printf '%s\n' "$1" | grep -qE -- "$2"
  case $? in 0) ;; 1) return 1 ;; *) disarmed "grep could not read a files pattern" ;; esac
  [ -n "$3" ] || return 0
  printf '%s\n' "$1" | grep -qE -- "$3"
  case $? in 0) return 1 ;; 1) return 0 ;; *) disarmed "grep could not read an exclude pattern" ;; esac
}

# verdict <action> <tag> <name> <message> <heading> <findings>
verdict() {
  local word=WARNING
  if [ "$1" = block ]; then word=BLOCKED; blocked=1; fi
  printf '[%s] %s: %s. %s\n%s\n%s' "$2" "$3" "$word" "$4" "$5" "$6" >&2
}

sections_judge() {
  grep -nE -- "$2" "$1" > "$work/req.raw"
  case $? in 0|1) ;; *) return 2 ;; esac
  cut -d: -f1 "$work/req.raw" > "$work/req" || return 2
  RL_LEVEL="$3" awk '
BEGIN { lvl = ENVIRON["RL_LEVEL"] + 0; hits = 0 }
FILENAME == ARGV[1] { ok[$1] = 1; next }
{
  line = $0; sub(/\r$/, "", line)
  fence = (substr(line, 1, 3) == "```" || substr(line, 1, 3) == "~~~")
  if (!infence && !fence) {
    n = 0; while (n < 7 && substr(line, n + 1, 1) == "#") n++
    c = substr(line, n + 1, 1)
    if (n >= 1 && n <= 6 && (c == " " || c == "\t" || c == "") && n <= lvl) {
      if (open && !sat) { print head; hits++ }
      open = (n == lvl); sat = 0; head = FNR ": " line
      next
    }
  }
  if (fence) infence = !infence
  if (open && (FNR in ok)) sat = 1
}
END { if (open && !sat) { print head; hits++ } exit (hits > 0) }
' "$work/req" "$1" || return $?
}

# ledger-entry-names-artefact: sections for [R:features-ledger-names-its-artefact].
d_ledger_entry_names_artefact() {
  local name='ledger-entry-names-artefact'
  local tag='R:features-ledger-names-its-artefact'
  local action='block'
  local message='A behaviour-ledger entry names no enforcing artefact. Every level-3 entry carries an Enforced by line naming the type, property test or unit test that holds it, or says NOTHING YET and goes to TODO.md. An Enforced by line placed under the next heading belongs to that entry, not this one.'
  local files_ere='((^|/)([^/]+/)*FEATURES\.md$)'
  local exclude_ere='((^|/)([^/]+/)*rules/[^/]*\.md$)|((^|/)([^/]+/)*hooks-pack/.*$)|((^|/)([^/]+/)*repo-pack/.*$)|((^|/)([^/]+/)*hooks/relearn/.*$)'
  local p hits found=""
  local require='[Ee]nforced by|NOTHING YET'
  local level=3
  while IFS= read -r -d '' p; do
    in_scope "$p" "$files_ere" "$exclude_ere" || continue
    case "$(git cat-file -t ":0:$p" 2>/dev/null)" in
      blob) ;;
      commit) continue ;;
      *) disarmed "$name: git could not read the staged $p" ;;
    esac
    git cat-file blob ":0:$p" > "$work/blob" || disarmed "$name: git could not read the staged $p"
    hits="$(sections_judge "$work/blob" "$require" "$level")"
    case $? in 0) continue ;; 1) ;; *) disarmed "$name: the sections judge could not read the staged $p" ;; esac
    found="$found$p:"$'\n'"$(printf '%s\n' "$hits" | sed 's/^/  /')"$'\n'
  done < "$work/staged"
  [ -n "$found" ] || return 0
  verdict "$action" "$tag" "$name" "$message" "Staged section(s) with no line matching the requirement:" "$found"
}

# listed-file-staged: listed-path for [R:no-secrets-in-config-repo].
d_listed_file_staged() {
  local name='listed-file-staged'
  local tag='R:no-secrets-in-config-repo'
  local action='block'
  local message='This path is on this clone'\''s machine-local list of files that must never be committed: secret-bearing or machine-specific configuration. Unstage it with git restore --staged, and keep it out of the index. The list itself is never committed; it is named per clone with git config --local relearn.listed-file-staged.list.'
  local files_ere='((^|/).*$)'
  local exclude_ere=''
  local p hits found=""
  local list
  list="$(git config --local --type=path --get "relearn.$name.list")" \
    || disarmed "$name has no list: name one with git config --local relearn.$name.list <file>"
  [ -f "$list" ] && [ -r "$list" ] || disarmed "$name: the list this clone names cannot be read"
  # One relative forward-slash path per line; blank lines and lines starting
  # with # are skipped. Any other line that is not such a path disarms the
  # check, and only its line number is printed: the list names what it guards.
  awk '
{ sub(/\r$/, "") }
/^#/ || $0 == "" { next }
{
  ok = ($0 !~ /^\//) && index($0, "\\") == 0 && index($0, ":") == 0
  n = split($0, seg, "/")
  for (i = 1; i <= n; i++) if (seg[i] == "" || seg[i] == "..") ok = 0
  if (ok) print; else bad = bad " " NR
}
END { if (bad != "") { print "line(s)" bad > "/dev/stderr"; exit 3 } }
' "$list" > "$work/list" 2> "$work/list.err" \
    || disarmed "$name: the list has an entry that is not a relative path, $(cat "$work/list.err")"
  while IFS= read -r -d '' p; do
    in_scope "$p" "$files_ere" "$exclude_ere" || continue
    grep -qxF -- "$p" "$work/list"
    case $? in 0) found="$found  $p"$'\n' ;; 1) ;; *) disarmed "$name: grep could not read the list" ;; esac
  done < "$work/staged"
  [ -n "$found" ] || return 0
  verdict "$action" "$tag" "$name" "$message" "Staged path(s) on this clone's list:" "$found"
}

# no-tool-attribution: line-regex for [R:no-tool-attribution-in-public-artefacts].
d_no_tool_attribution() {
  local name='no-tool-attribution'
  local tag='R:no-tool-attribution-in-public-artefacts'
  local action='block'
  local message='This line is tool attribution: a co-author trailer, a session link or a generated-with banner. It travels with whatever the file becomes, a commit message, a PR body or a published page. Remove it. A document that quotes the form as an example marks the line with the override token.'
  local files_ere='((^|/).*$)'
  local exclude_ere='((^|/)([^/]+/)*rules/[^/]*\.md$)|((^|/)([^/]+/)*hooks-pack/.*$)|((^|/)([^/]+/)*repo-pack/.*$)|((^|/)([^/]+/)*hooks/relearn/.*$)'
  local p hits found=""
  local pattern='^[Cc]o-[Aa]uthored-[Bb]y: .*([Cc]laude|anthropic\.com)|^Claude-Session: |Generated with \[?Claude Code'
  while IFS= read -r -d '' p; do
    in_scope "$p" "$files_ere" "$exclude_ere" || continue
    case "$(git cat-file -t ":0:$p" 2>/dev/null)" in
      blob) ;;
      commit) continue ;;
      *) disarmed "$name: git could not read the staged $p" ;;
    esac
    git cat-file blob ":0:$p" > "$work/blob" || disarmed "$name: git could not read the staged $p"
    hits="$(grep -anE -- "$pattern" "$work/blob")"
    case $? in 0) ;; 1) continue ;; *) disarmed "$name: grep could not read the pattern" ;; esac
    # A line carrying 'allow:attribution' is a deliberate, marked exception.
    hits="$(printf '%s\n' "$hits" | grep -vF -- 'allow:attribution')"
    [ -n "$hits" ] || continue
    found="$found$p:"$'\n'"$(printf '%s\n' "$hits" | sed 's/^/  /')"$'\n'
  done < "$work/staged"
  [ -n "$found" ] || return 0
  verdict "$action" "$tag" "$name" "$message" "Offending staged line(s):" "$found"
  printf 'A deliberate exception is marked on its own line with: %s\n' 'allow:attribution' >&2
}

[ "$#" -gt 0 ] || set -- 'ledger-entry-names-artefact' 'listed-file-staged' 'no-tool-attribution'
for selected in "$@"; do
  case "$selected" in
    'ledger-entry-names-artefact') d_ledger_entry_names_artefact ;;
    'listed-file-staged') d_listed_file_staged ;;
    'no-tool-attribution') d_no_tool_attribution ;;
    *) disarmed "no commit-time detector is named $selected" ;;
  esac
done
exit "$blocked"

